import datetime


def build_report(rows, kind, fmt):
    out = []
    total = 0.0
    for r in rows:
        if kind == 'daily':
            if r['amount'] > 0:
                total = total + float(r['amount'])
                out.append(str(r['id']) + ',' + str(r['amount']) + ',' + str(datetime.datetime.now()))
        elif kind == 'weekly':
            if r['amount'] > 0:
                total = total + float(r['amount']) * 7
                out.append(str(r['id']) + ',' + str(r['amount'] * 7) + ',' + str(datetime.datetime.now()))
        elif kind == 'monthly':
            if r['amount'] > 0:
                total = total + float(r['amount']) * 30
                out.append(str(r['id']) + ',' + str(r['amount'] * 30) + ',' + str(datetime.datetime.now()))
    if fmt == 'csv':
        return '\n'.join(out) + '\n' + 'total,' + str(total)
    elif fmt == 'json':
        return '{"rows": [' + ','.join('"' + o + '"' for o in out) + '], "total": ' + str(total) + '}'
    return out
EOF
